"""Ablation rows extracted from the SOTA dossiers of 2026-09-25 for CL Design Principle DECLARATION_1; every number appears in a verbatim quote.

Sources: docs/citations/cl_sota_replay_2026-09-25.md, cl_sota_distill_2026-09-25.md, cl_sota_reg_plasticity_2026-09-25.md,
forever_2026-09-25.md, and the raw text extractions they cite (session scratchpad lit0925/clsota/{replay,distill,reg}/ and
lit0925/forever/). Each 'quote' is a verbatim string (or list of strings) from the dossier or the raw text, matched after
html-unescape, removal of PDF soft-hyphen breaks (U+FFFE, U+00AD) and whitespace collapse; both numbers of the row appear in it.

Conventions:
- 'setting' starts with 'class-IL', 'task-IL', 'GCIL', or names a non-image setting (M17, M18); 'online'/'offline' is stated.
  Task-IL rows are recorded where the declaration's setting preference does not exclude them (M1, M2, M13, M14); M12 task-IL rows
  are not recorded because DECLARATION_1 marks M12 task-incremental as S.
- 'with_*' is the arm WITH the mechanism (or the method the mechanism names first); 'without_*' the other arm.
- std fields hold the paper's printed +/- when it is a standard deviation (or unspecified +/-); None when no deviation is printed or
  when the printed +/- is a standard error (van de Ven et al.), as stated in the row's note.
- Rows are not graded here (no AGREES/DISAGREES).
- CIFAR-10 rows are omitted for every mechanism that has a CIFAR-100 row (all mechanisms M1-M14 do).
- Head-to-heads not recorded by design: DER++ vs ER (M4 is defined as DER vs ER); SS-IL, BiC, LUCIR vs ER (confounded by extra
  distillation); cross-table pairs (e.g. GSA Table 3 ablations vs GSA Table 1, bag-of-tricks Table III vs Table I).
"""

